-- Connecting a venue's payment account (#109; D125 2.3, 2.4). Generated by drizzle-kit, then this
-- comment added by hand. No data. `provider_notices.kind` gains `account` (the venue's account
-- changed: the worker re-reads the connection) and `access_lost` (the venue took Restro's access
-- away: paying pauses at once).
ALTER TABLE "restro"."provider_notices" DROP CONSTRAINT "provider_notices_kind";--> statement-breakpoint
ALTER TABLE "restro"."provider_notices" ADD CONSTRAINT "provider_notices_kind" CHECK ("restro"."provider_notices"."kind" in ('payment', 'refund', 'dispute', 'account', 'access_lost', 'other'));